import { describe, expect, it } from "vitest";
import {
  PLANS,
  ROLE_SHORTCUT_LIMITS,
  PLAN_CONFIG_VERSION,
  QUOTA_TIMEZONE,
} from "@/lib/plans";

describe("plan configuration", () => {
  it("defines the exact JSON-safe plans and current role limits", () => {
    expect(JSON.parse(JSON.stringify(PLANS))).toEqual({
      FREE: {
        monthlyEmails: 15,
        dailyEmails: 3,
        campaignRecipients: 3,
        savedTemplates: 1,
        resumeAttachment: true,
        tracking: "basic",
        manualRepeatSend: true,
        historyShortlist: false,
        markReplied: false,
        csvImport: false,
        followUpReminders: false,
        followUpDelayOptions: [],
        prioritySupport: false,
        blackThemes: false,
        previewHighlightColors: false,
        recipientRoleOverride: false,
      },
      PAID: {
        monthlyEmails: 300,
        dailyEmails: 20,
        campaignRecipients: 10,
        savedTemplates: null,
        resumeAttachment: true,
        tracking: "basic",
        manualRepeatSend: true,
        historyShortlist: true,
        markReplied: true,
        csvImport: true,
        followUpReminders: true,
        followUpDelayOptions: [3, 7, 14],
        prioritySupport: true,
        blackThemes: true,
        previewHighlightColors: true,
        recipientRoleOverride: true,
      },
    });
    expect(ROLE_SHORTCUT_LIMITS).toEqual({ free: 2, premium: 8 });
    expect(PLAN_CONFIG_VERSION).toBe(5);
    expect(QUOTA_TIMEZONE).toBe("UTC");
    expect(JSON.parse(JSON.stringify(PLANS))).toEqual(PLANS);
  });
});
